def p_at_total(p, i):
    return p[i] if 0 <= i < len(p) else 0


def grid_at(p, n, i, j):
    return p_at_total(p, i * n + j)


def grid_row(p, n, i):
    return [grid_at(p, n, i, j) for j in range(max(n, 0))]


def grid_rows(p, n):
    return [grid_row(p, n, i) for i in range(max(n, 0))]


